import{_ as i,a0 as l,w as o,s as r,ao as h,I as t,x as a,a1 as e,A as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"我是如何开始踏上 bash 脚本编程之路的？ | LCTT x X-CMD","titleTemplate":false,"description":"我是如何开始踏上 bash 脚本编程之路的？ | LCTT (201706) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"我是如何开始踏上 bash 脚本编程之路的？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"我是如何开始踏上 bash 脚本编程之路的？ | LCTT (201706) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201706/20170515 How I got started with bash scripting","title":"我是如何开始踏上 bash 脚本编程之路的？","tag":"201706","desc":""},"relativePath":"201706/20170515 How I got started with bash scripting.md","filePath":"[post].md"}'),d={name:"201706/20170515 How I got started with bash scripting.md"};function g(c,s,u,b,m,k){const n=l("Link");return o(),r("div",null,[s[13]||(s[13]=h(`<h1 id="我是如何开始踏上-bash-脚本编程之路的" tabindex="-1">我是如何开始踏上 bash 脚本编程之路的？ <a class="header-anchor" href="#我是如何开始踏上-bash-脚本编程之路的" aria-label="Permalink to “我是如何开始踏上 bash 脚本编程之路的？”">​</a></h1><blockquote><p>通过一些简单的 Google 搜索，即使是编程入门者也可以尝试编写代码将以往枯燥和冗长的任务自动化。</p></blockquote><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/images/life/computer_happy_sad_developer_programming.png?itok=5E3k_t_r" alt="How Google helped me learn bash scripting" title="How Google helped me learn bash scripting"></p><p>我前几天写了一个脚本。对于一些人来说，这句话听起来没什么了不起的。而对于另一些人来说，这句话意义重大。要知道，我不是一个程序员，而是一个作家。</p><h3 id="我需要解决什么" tabindex="-1">我需要解决什么？ <a class="header-anchor" href="#我需要解决什么" aria-label="Permalink to “我需要解决什么？”">​</a></h3><p>我的问题相当简单：我需要将工程文件进行分类。这些文件可以从一个网站 URL 以 .zip 的格式下载。当我正手工将它们拷贝到我的电脑桌面，并移动到一个已按照我文件分类的需要进行了结构化的目录时，一位作家同事给我提了建议：<em>“不就是写个脚本的事吗？”</em></p><p>我心想：<em>“就写个脚本？”</em>——说得好像这是世界上最容易做的事情一样。</p><h3 id="google-是如何解救我的" tabindex="-1">Google 是如何解救我的？ <a class="header-anchor" href="#google-是如何解救我的" aria-label="Permalink to “Google 是如何解救我的？”">​</a></h3><p>同事的问题促使我思考，并且经过思考后，我进行了 Google 搜索。</p><p><strong>Linux 上使用的是什么脚本编程语言？</strong></p><p>这是我第一个 Google 搜索的准则。也许很多人心里会想：“她太笨了！”是的，我很笨。不过，这的确使我走上了一条解决问题的道路。最常见的搜索结果是 Bash 。嗯，我听说过 Bash 。呃，我要分类的文件中有一个里面就有 Bash，那无处不在的 <code>#!/bin/bash</code> 。我重新看了下那个文件，我知道它的用途，因为我需要将它分类。</p><p>这引导我进行了下一个 Google 搜索。</p><p><strong>如何从一个 URL 下载 zip 文件？</strong></p><p>那确实是我的基本任务。我有一个带有 .zip 文件的 URL ，它包含有所有我需要分类的文件，所以我寻求万能的 Google 的帮助。搜索到的精华内容和其它一些结果引导我使用 Curl 。但最重要的是：我不仅找到了 Curl ，其中一条置顶的搜索结果还展示了一个使用 Curl 去下载并解压 .zip 文件的 Bash 脚本。这超出了我本来想寻求的答案，但那也使我意识到在 Google 搜索具体的请求可以得到我写这个脚本需要的信息。所以，在这个收获的推动下，我写了最简单的脚本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/sh</span></span>
<span class="line"><span></span></span>
<span class="line"><span>curl http://rather.long.url | tar -xz -C my_directory --strip-components=1</span></span></code></pre></div><p>我迫不及待地运行看看。但我发现一个问题： URL 是会变的，根据我要访问的文件的分组不同而不同。我有新的问题需要解决，这使我进行了下一轮搜索。</p><p><strong>参数如何传递给 Bash 脚本？</strong></p><p>我需要以不同的 URL 和不同的最终目录来运行此脚本。 Google 向我展示了如何使用 <code>$1</code>、<code>$2</code> 等等来替换我在命令行中运行脚本时输入的内容。比如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>bash myscript.sh http://rather.long.url my_directory</span></span></code></pre></div><p>这就好多了。一切如我所愿，灵活，实用。最重要的是我只要输入一条简短的命令就可以节省 30 分钟无聊的复制、粘贴工作。这个早上的时间花得值得。</p><p>然后我发现还有一个问题：我很健忘，并且我知道我几个月才运行一次这个脚本。这留给我两个疑问：</p><ul><li>我要如何记得运行脚本时输入什么（URL 先，还是目录先）？</li><li>如果我被货车撞了，其它作家如何知道该怎样运行我的脚本？</li></ul><p>我需要一个使用说明 —— 如果我使用不正确，则脚本会提示。比如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>usage: bash yaml-fetch.sh &lt;&#39;snapshot_url&#39;&gt; &lt;directory&gt;</span></span></code></pre></div><p>否则，则直接运行脚本。我的下一个搜索是：</p><p><strong>如何在 Bash 脚本里使用 “if/then/else”?</strong></p><p>幸运的是，我已经知道编程中 <code>if/then/else</code> 的存在。我只要找出如何使用它的方法。在这个过程中，我也学到了如何在 Bash 脚本里使用 <code>echo</code> 打印。我的最终成果如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/sh</span></span>
<span class="line"><span></span></span>
<span class="line"><span>URL=$1</span></span>
<span class="line"><span>DIRECTORY=$2</span></span>
<span class="line"><span></span></span>
<span class="line"><span>if [ $# -eq 0 ];</span></span>
<span class="line"><span> then</span></span>
<span class="line"><span> echo &quot;usage: bash yaml-fetch.sh &lt;&#39;snapshot_url&#39;&gt; &lt;directory&gt;&quot;.</span></span>
<span class="line"><span> else</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 如果目录不存在则创建它</span></span>
<span class="line"><span> echo &#39;create directory&#39;</span></span>
<span class="line"><span></span></span>
<span class="line"><span> mkdir $DIRECTORY</span></span>
<span class="line"><span></span></span>
<span class="line"><span> # 下载并解压 yaml 文件</span></span>
<span class="line"><span> echo &#39;fetch and untar the yaml files&#39;</span></span>
<span class="line"><span></span></span>
<span class="line"><span> curl $URL | tar -xz -C $DIRECTORY --strip-components=1</span></span>
<span class="line"><span>fi</span></span></code></pre></div><h3 id="google-和脚本编程如何颠覆我的世界" tabindex="-1">Google 和脚本编程如何颠覆我的世界？ <a class="header-anchor" href="#google-和脚本编程如何颠覆我的世界" aria-label="Permalink to “Google 和脚本编程如何颠覆我的世界？”">​</a></h3><p>好吧，这稍微有点夸大，不过现在是 21 世纪，学习新东西（特别是稍微简单的东西）比以前简单多了。我所学到的（除了如何写一个简短的、自动分类的 Bash 脚本之外）是如果我有疑问，那么有很大可能性是其它人在之前也有过相同的疑问。当我困惑时，我可以问下一个问题，再下一个问题。最后，我不仅拥有了脚本，还拥有了可以一直拥有并可以简化其它任务的新技能，这是我之前所没有的。</p><p>别止步于第一个脚本（或者编程的第一步）。这是一个技能，和其它的技能并无不同，有大量的信息可以在这一路上帮助你。你无需阅读大量的书或参加一个月的课程。你可以像婴儿学步那样简单地开始写脚本，然后掌握技能并建立自信。人们总有写成千上万行代码的需求，并对它进行分支、合并、修复错误。但是，通过简单的脚本或其它方式来自动化、简单化任务的需求也一样强烈。这样的一个小脚本和小小的自信就能够让你启程脚本编程之路。</p><p>（题图： opensource.com）</p><hr><p>作者简介：</p><p>Sandra McCann 是一位 Linux 和开源技术的倡导者。她是一位软件开发者、学习资源内容架构师、内容创作者。Sandra McCann 目前是位于韦斯特福德马萨诸塞州的红帽公司的内容创作者，专注于 OpenStack 和 NFV 技术。</p><hr>`,36)),t("p",null,[s[1]||(s[1]=a("via: ",-1)),e(n,{href:"https://opensource.com/article/17/5/how-i-learned-bash-scripting"},{default:p(()=>[...s[0]||(s[0]=[a("https://opensource.com/article/17/5/how-i-learned-bash-scripting",-1)])]),_:1})]),t("p",null,[s[5]||(s[5]=a("作者：",-1)),e(n,{href:"https://opensource.com/users/sandra-mccann"},{default:p(()=>[...s[2]||(s[2]=[a("Sandra McCann",-1)])]),_:1}),s[6]||(s[6]=a(" 译者：",-1)),e(n,{href:"https://github.com/xllc"},{default:p(()=>[...s[3]||(s[3]=[a("xllc",-1)])]),_:1}),s[7]||(s[7]=a(" 校对：",-1)),e(n,{href:"https://github.com/wxy"},{default:p(()=>[...s[4]||(s[4]=[a("wxy",-1)])]),_:1})]),t("p",null,[s[10]||(s[10]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[8]||(s[8]=[a("LCTT",-1)])]),_:1}),s[11]||(s[11]=a(" 原创编译，",-1)),e(n,{href:"https://linux.cn/"},{default:p(()=>[...s[9]||(s[9]=[a("Linux中国",-1)])]),_:1}),s[12]||(s[12]=a(" 荣誉推出",-1))])])}const x=i(d,[["render",g]]);export{y as __pageData,x as default};
